func OSIsSystemDarkAppearance() bool {
	var osxMode *NSString = NSUserDefaultsStandardUserDefaults().StringForKey(NSStringStringWith("AppleInterfaceStyle"))
	return osxMode != (nil) && ("Dark" == osxMode.GetString())
}

